"""Native-media transport regression tests; generated bytes only, no devices."""
from __future__ import annotations

import asyncio
from pathlib import Path
import unittest

from uvicorn.config import Config
from uvicorn.protocols.websockets.wsproto_impl import WSProtocol
from uvicorn.server import ServerState
from wsproto import ConnectionType, WSConnection, events


ROOT = Path(__file__).resolve().parents[1]


class MemoryTransport(asyncio.Transport):
    def __init__(self) -> None:
        self.output = bytearray()
        self.closed = False
        self.read_paused = False

    def get_extra_info(self, name: str, default=None):
        if name in {"sockname", "peername"}:
            return ("127.0.0.1", 12345)
        return default

    def write(self, data: bytes) -> None:
        self.output.extend(data)

    def is_closing(self) -> bool:
        return self.closed

    def close(self) -> None:
        self.closed = True

    def pause_reading(self) -> None:
        self.read_paused = True

    def resume_reading(self) -> None:
        self.read_paused = False

    def take_output(self) -> bytes:
        output = bytes(self.output)
        self.output.clear()
        return output


class WebSocketTransportTests(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self) -> None:
        self.state = ServerState()
        self.received: asyncio.Queue = asyncio.Queue()

        async def app(scope, receive, send):
            self.assertEqual((await receive())["type"], "websocket.connect")
            if scope["path"] == "/rejected":
                await send({"type": "websocket.close", "code": 1008})
                return
            await send({"type": "websocket.accept"})
            while True:
                message = await receive()
                self.received.put_nowait(message)
                if message["type"] == "websocket.disconnect":
                    return

        config = Config(
            app, ws="wsproto", log_config=None, log_level="critical",
            lifespan="off", ws_ping_interval=None, ws_max_size=1024,
        )
        self.protocol = WSProtocol(config, self.state, {})
        self.transport = MemoryTransport()
        self.client = WSConnection(ConnectionType.CLIENT)
        self.protocol.connection_made(self.transport)

    async def asyncTearDown(self) -> None:
        self.protocol.stop_keepalive()
        tasks = list(self.state.tasks)
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        self.state.connections.discard(self.protocol)

    async def connect(self, target: str = "/native") -> list:
        self.protocol.data_received(self.client.send(events.Request(host="localhost", target=target)))
        # Running the ASGI handshake must not require a real socket or server.
        for _ in range(20):
            if self.transport.output:
                break
            await asyncio.sleep(0)
        self.assertTrue(self.transport.output, "ASGI handshake did not complete")
        return self.client_events()

    def client_events(self) -> list:
        self.client.receive_data(self.transport.take_output())
        return list(self.client.events())

    async def test_keepalive_and_incoming_audio_survive_blocked_media_write(self) -> None:
        self.assertIsInstance((await self.connect())[0], events.AcceptConnection)
        for index in range(12):
            media = b"TSCV1-synthetic-picture-" + bytes([index])
            self.protocol.pause_writing()
            writer = asyncio.create_task(self.protocol.send({"type": "websocket.send", "bytes": media}))
            try:
                await asyncio.sleep(0)
                self.assertFalse(writer.done(), "transport ignored backpressure")

                # This automatic pong used to compete with media in the
                # legacy drain waiter, raising AssertionError and disconnecting.
                ping = b"tater-" + bytes([index])
                self.protocol.data_received(self.client.send(events.Ping(payload=ping)))
                replies = self.client_events()
                self.assertEqual(len(replies), 1)
                self.assertIsInstance(replies[0], events.Pong)
                self.assertEqual(replies[0].payload, ping)
                self.assertFalse(writer.done())

                audio = b"\0\1" * 40
                self.protocol.data_received(self.client.send(events.BytesMessage(data=audio)))
                incoming = await asyncio.wait_for(self.received.get(), timeout=1)
                self.assertEqual(incoming, {"type": "websocket.receive", "bytes": audio})
                self.assertFalse(self.transport.closed)

                self.protocol.resume_writing()
                await asyncio.wait_for(writer, timeout=1)
                pictures = self.client_events()
                self.assertEqual(len(pictures), 1)
                self.assertIsInstance(pictures[0], events.BytesMessage)
                self.assertEqual(pictures[0].data, media)
            finally:
                writer.cancel()
                await asyncio.gather(writer, return_exceptions=True)

    async def test_fragmented_binary_message_keeps_existing_byte_budget(self) -> None:
        await self.connect()
        self.protocol.data_received(self.client.send(events.BytesMessage(data=b"a" * 600, message_finished=False)))
        self.assertTrue(self.received.empty())
        self.protocol.data_received(self.client.send(events.BytesMessage(data=b"b" * 600)))
        replies = self.client_events()
        self.assertIsInstance(replies[0], events.CloseConnection)
        self.assertEqual(replies[0].code, 1009)
        self.assertTrue(self.transport.closed)
        incoming = await asyncio.wait_for(self.received.get(), timeout=1)
        self.assertEqual(incoming["type"], "websocket.disconnect")
        self.assertEqual(incoming["code"], 1009)

    async def test_asgi_can_still_reject_before_websocket_accept(self) -> None:
        replies = await self.connect("/rejected")
        self.assertIsInstance(replies[0], events.RejectConnection)
        self.assertEqual(replies[0].status_code, 403)
        self.assertTrue(self.transport.closed)


class WebSocketStartupTests(unittest.TestCase):
    def test_every_runtime_installs_and_explicitly_selects_wsproto(self) -> None:
        launcher = (ROOT / "run_ui.sh").read_text(encoding="utf-8")
        self.assertIn("--ws wsproto", launcher)
        self.assertIn("from uvicorn.protocols.websockets.wsproto_impl import WSProtocol", launcher)
        for filename in ("requirements.txt", "requirements-edge.txt"):
            requirements = (ROOT / filename).read_text(encoding="utf-8").splitlines()
            self.assertIn("uvicorn>=0.49.0", requirements)
            self.assertIn("wsproto>=1.3.0,<2", requirements)
        setup = (ROOT / "setup_tater.sh").read_text(encoding="utf-8")
        self.assertIn('"uvicorn", "wsproto", "redis"', setup)


if __name__ == "__main__":
    unittest.main()
